//copied/pasted and slighly modified from Daniel Shiffman:
//https://p5js.org/examples/simulate-flocking.html
//Thanks Dan!
class Boid {

  constructor(x, y) {
    this.location=new p5.Vector(x, y);
    this.acceleration = new p5.Vector(random(-2, 2), random(-2, 2));
    this.velocity = new p5.Vector(random(-maxspeedfactor, maxspeedfactor), random(-maxspeedfactor, maxspeedfactor));
    this.radius = random(15, 100);
    this.wandertheta = 0;
    this.maxspeed = random(2*maxspeedfactor, 7*maxspeedfactor);
    this.maxforce = random(0.02, .05);
    this.dia=2*this.radius;
    this.wanderR = random(10, 50);         // Radius for the "wander circle"
    this.wanderD = random(100, 200);         // Distance from the "wander circle"
    this.maxchange = 0.7;
  }
  fly() {
    this.maxspeed = random(2*maxspeedfactor, 10*maxspeedfactor);
    this.update();
    this.borders();
    this.wander();
  }
  walk() {    
    this.maxspeed= random(maxspeedfactor, 2*maxspeedfactor);
    this.update();
    this.borders();
    this.wander();
  }
  // Method to update location
  update() {
    // Update velocity
    this.velocity.add(this.acceleration);
    // Limit speed
    this.velocity.limit(this.maxspeed);
    this.location.add(this.velocity);
  }

  wander() {
    this.wandertheta += random(-this.maxchange, this.maxchange);     // Randomly change wander theta

    // Now we have to calculate the new location to steer towards on the wander circle
    this.circleloc =this.velocity.copy();    // Start with velocity
    this.circleloc.normalize();            // Normalize to get heading
    this.circleloc.mult(this.wanderD);          // Multiply by distance
    this.circleloc.add(this.location);               // Make it relative to boid's location

    var h =this.velocity.heading();        // We need to know the heading to offset wandertheta

    this.circleOffSet = new p5.Vector(this.wanderR*cos(this.wandertheta+h), this.wanderR*sin(this.wandertheta+h));
    this.target = p5.Vector.add(this.circleloc, this.circleOffSet);
    this.seek(this.target);
  }  

  applyForce(force) {
    // We could add mass here if we want A = F / M
    this.acceleration.add(force);
  }


  // A method that calculates and applies a steering force towards a target
  // STEER = DESIRED MINUS VELOCITY
  seek(target) {
    var desired = p5.Vector.sub(target, this.location);  // A vector pointing from the location to the target
    // Normalize desired and scale to maximum speed
    desired.normalize();
    desired.mult(this.maxspeed);
    // Steering = Desired minus Velocity
    var steer = p5.Vector.sub(desired, this.velocity);
    steer.limit(this.maxforce);  // Limit to maximum steering force
    this.applyForce(steer);
    return steer;
  }

  // Wraparound
  borders() {
    if (this.location.x < -this.radius) this.location.x = width+this.radius;
    if (this.location.y < -this.radius) this.location.y = height+this.radius;
    if (this.location.x > width+this.radius) this.location.x = -this.radius;
    if (this.location.y > height+this.radius) this.location.y = -this.radius;
  }
  // We accumulate a new acceleration each time based on three rules
  flock(boids) {
    let sep = this.separate(boids);   // Separation
    let ali = this.align(boids);      // Alignment
    let coh = this.cohesion(boids);   // Cohesion
    // Arbitrarily weight these forces
    sep.mult(1.5);
    ali.mult(1.0);
    coh.mult(1.0);
    // Add the force vectors to acceleration
    this.applyForce(sep);
    this.applyForce(ali);
    this.applyForce(coh);
  }
  // Separation
  // Method checks for nearby boids and steers away
  separate(boids) {
    let desiredseparation = .15*width;
    let steer = createVector(0, 0);
    let count = 0;
    // For every boid in the system, check if it's too close
    for (let i = 0; i < boids.length; i++) {
      let d = p5.Vector.dist(this.location, boids[i].location);
      // If the distance is greater than 0 and less than an arbitrary amount (0 when you are yourself)
      if ((d > 0) && (d < desiredseparation)) {
        // Calculate vector pointing away from neighbor
        let diff = p5.Vector.sub(this.location, boids[i].location);
        diff.normalize();
        diff.div(d);        // Weight by distance
        steer.add(diff);
        count++;            // Keep track of how many
      }
    }
    // Average -- divide by how many
    if (count > 0) {
      steer.div(count);
    }
    // As long as the vector is greater than 0
    if (steer.mag() > 0) {
      // Implement Reynolds: Steering = Desired - Velocity
      steer.normalize();
      steer.mult(this.maxspeed);
      steer.sub(this.velocity);
      steer.limit(this.maxforce);
    }
    return steer;
  }
  // Alignment
  // For every nearby boid in the system, calculate the average velocity
  align(boids) {
    let neighbordist = .1*width;
    let sum = createVector(0, 0);
    let count = 0;
    for (let i = 0; i < boids.length; i++) {
      let d = p5.Vector.dist(this.location, boids[i].location);
      if ((d > 0) && (d < neighbordist)) {
        sum.add(boids[i].velocity);
        count++;
      }
    }
    if (count > 0) {
      sum.div(count);
      sum.normalize();
      sum.mult(this.maxspeed);
      let steer = p5.Vector.sub(sum, this.velocity);
      steer.limit(this.maxforce);
      return steer;
    } else {
      return createVector(0, 0);
    }
  }

  // Cohesion
  // For the average location (i.e. center) of all nearby boids, calculate steering vector towards that location
  cohesion(boids) {
    let neighbordist = .3*width;
    let sum = createVector(0, 0);   // Start with empty vector to accumulate all locations
    let count = 0;
    for (let i = 0; i < boids.length; i++) {
      let d = p5.Vector.dist(this.location, boids[i].location);
      if ((d >0) && (d < neighbordist)) {
        sum.add(boids[i].location); // Add location
        count++;
      }
    }
    if (count > 0) {
      sum.div(count);
      return this.seek(sum);  // Steer towards the location
    } else {
      return new p5.Vector(0, 0);
    }
  }
}


// === Tab: Elytron ===
class Elytron extends Part{
  constructor(parent, side) {
    super(parent);
    this.side=side;
    this.col=colors[this.parent.family];
    this.location=new p5.Vector(0, -.5*this.parent.body.h);
    this.rot=0;
		this.w=this.size;
    this.h=this.parent.body.h;
    this.opens=false;
    this.shuts=false;
  }
  display() {

    ellipseMode(CORNER);
    push();
    translate(this.location.x, this.location.y);
    if (this.opens) {      
      if ((this.side>0 && this.rot>.9)||(this.side<0 && this.rot<-.9))
      {
        this.opens=false;
        this.parent.opened=true;
      } else this.rot+=this.side*this.parent.vibratingSpeed;
    } else if (this.shuts) {       
      if ((this.side>0 && this.rot<=this.parent.vibratingSpeed)||(this.side<0 && this.rot>=this.parent.vibratingSpeed))
      {
        this.shuts=false;
        this.rot=0;
        this.parent.close=true;
      } else this.rot-=this.side*this.parent.vibratingSpeed;
    }
    rotate(this.rot);
    strokeWeight(.05*this.size);
    stroke(this.parent.elytronl.scol);
    fill(this.parent.elytronl.col);
    arc(-.5*this.w, 0, this.w, this.h, this.side*HALF_PI, PI+this.side*HALF_PI, CHORD);
    pop();
    ellipseMode(CENTER);
  }
}

// === Tab: Head ===
class Head extends Part{
  constructor(parent) {
    super(parent);
    this.ycol=colors[int(random(ncolors))];
    this.ycol=color(360-hue(window.color(this.col)),255,255-brightness(window.color(this.col)),255);
    this.location=new p5.Vector(0, -.5*this.parent.body.h);
    this.coeff=.7;
		this.size*=this.coeff;
    this.len=random(.8,1.1)*this.size;
  }
  display() {
    if(this.parent.close && !this.parent.walking) this.location.y=-.35*this.parent.body.h;
    else  this.location.y=-.5*this.parent.body.h;
    fill(this.col);
    strokeWeight(this.parent.size*.05/this.coeff);
    stroke(this.scol);
    line(0, this.location.y-.5*this.size, 0, this.location.y-this.len);
    ellipse(this.location.x, this.location.y, this.size, this.size);
    if(!this.parent.close ||this.parent.walking)fill(this.ycol); else fill(0);
    ellipse(this.location.x-.3*this.size, this.location.y-.3*this.size, .3*this.size, .3*this.size);
    ellipse(this.location.x+.3*this.size, this.location.y-.3*this.size, .3*this.size, .3*this.size);
    noFill();
    arc(0, this.location.y-1.3*this.size, this.size, this.size, 0, PI);
  }
}

// === Tab: Leg ===
class Leg extends Part{
  constructor(parent, type, side,group) {
    super(parent);
    this.group=group;
    this.side=side;
    this.type=type;
		this.len=.3*this.size;
    this.col=this.parent.head.col;
    this.scol=this.parent.head.scol;
    this.location=new p5.Vector(.3*this.size*this.side,-.2*this.size*this.type);    
    this.initrot=-(HALF_PI+.8*this.type)*this.side;
  }
  display() {
    let sangle=sin(8*this.parent.vibratingSpeed*frameCount);
    push();
    translate(this.location.x, this.location.y);
    strokeWeight(.05*this.size);
    stroke(this.scol);
    rotate(this.initrot)
    if(this.parent.walking){
      this.len=.4*this.size;
      if(this.group==1 && sangle>.3)rotate(-1.2*this.side*sangle-.2*this.type);
      if(this.group==2 && sangle<-.3) rotate(1.2*this.side*sangle+.2*this.type);
    }
    else this.len=.3*this.size;
    line(0,0,0,this.len);
    line(0,this.len,((abs(this.type)-1)-this.side)*.4*this.len,(1.3+.8*abs(this.type))*this.len);//1.4+.3*abs(this.type))*this.len);
    ellipse(((abs(this.type)-1)-this.side)*.4*this.len,(1.3+.8*abs(this.type))*this.len,.2*this.len,.2*this.len);
    pop();
  }
}

// === Tab: Scarab ===
class Scarab extends Boid {
  constructor() {
    var size=min(height, width)*pow(random(minsize, maxsize),1.2);
    super(random(size, width-size), random(1.5*size, height-size));
    this.family=int(random(ncolors*.4,ncolors*.8));
    this.size=size;
    this.col=colors[this.family];
    this.vibratingSpeed=map(this.size, minsize*height, maxsize*height, .05, .01);
    this.flying=false;
    this.walking=false;
    this.opened=false;
    this.close=true;
    this.still=true;
    this.born=millis();
    this.alive=false;
    this.friends=[];
  }
  createParts() {
    this.body=new Body(this);
    this.head=new Head(this);
    this.elytronl=new Elytron(this, -1);
    this.elytronr=new Elytron(this, 1);
    this.wingl=new Wing(this, -1);
    this.wingr=new Wing(this, 1);
    this.frontlegl=new Leg(this, 1, -1, 1);
    this.frontlegr=new Leg(this, 1, 1, 2);
    this.midlegl=new Leg(this, .3, -1, 2);
    this.midlegr=new Leg(this,.3, 1, 1);
    this.backlegl=new Leg(this, -1, -1, 1);
    this.backlegr=new Leg(this, -1, 1, 2);
  }
  behave() {
    if (millis()-this.born>100*this.size) {
      this.alive=true;
      if (random(1)>.998 && !this.opened)
        this.startopen();//97
      if (random(1)>.995&& !this.close)this.startshut();
      if (random(1)>.992 && this.close) {
        this.walking=true;
      }
      if (random(1)>.999)this.walking=false;
      if (this.opened) {        
        this.flying=true;
				this.walking=false;
        this.friends=[];
        for (var i=0; i<scarabs.length; i++) {
          if (scarabs[i].family==this.family && scarabs[i].flying)this.friends.push(scarabs[i]);
        }
        this.flock(this.friends);
				this.fly();
      }
      if (this.walking) {
				this.flying=false;
        this.friends=[];
        for (var i=0; i<scarabs.length; i++) {
          if (scarabs[i].family==this.family && !scarabs[i].flying)this.friends.push(scarabs[i]);
        }
        this.enemies=[];
        for (var i=0; i<scarabs.length; i++) {
          if (scarabs[i].family!=this.family)this.enemies.push(scarabs[i]);
        }
        this.separate(this.enemies);              
        this.flock(this.friends);
				this.walk();
      }
    }
    this.display();
  }
  startopen() {
    this.close=false;
    this.elytronl.opens=true;
    this.elytronr.opens=true; 
    this.elytronl.shuts=false;
    this.elytronr.shuts=false;
  }
  startshut() {
    this.opened=false;
    this.elytronl.shuts=true;
    this.elytronr.shuts=true;  
    this.elytronl.opens=false;
    this.elytronr.opens=false;
  }

  display() {
    if (!this.alive) {
      push();
      translate(this.location.x, this.location.y);			
      rotate(this.velocity.heading()+HALF_PI);
      fill(this.elytronl.col);
      noStroke();
      ellipse(0, 0, this.size*(millis()-this.born)/(50*this.body.h), this.size*(millis()-this.born)/(50*this.size));
      pop();
    } else {			
      push();
      translate(this.location.x, this.location.y);
			textSize(32);
			if(debug)text(this.family,0,0);
      rotate(this.velocity.heading()+HALF_PI);
      strokeWeight(this.size*.05);
      this.head.display();    
      this.frontlegl.display();
      this.frontlegr.display();
      this.midlegl.display();
      this.midlegr.display();
      this.backlegl.display();
      this.backlegr.display();
      this.body.display();  
      if (!this.close) {
        this.wingl.display();
        this.wingr.display();
      }
      this.elytronl.display();
      this.elytronr.display(); 
      strokeWeight(1);
      pop();
      if (debug) {
        textSize(36);
        text(this.close, this.location.x, this.location.y);
      }
    }
  }
}


// === Tab: Wing ===
class Wing extends Part{
  constructor(parent, side) {
    super(parent);
    this.side=side;
    this.col=color(random(360), random(200,255), random(200, 255), random(220, 255));
    this.location=new p5.Vector(0, -.5*this.parent.body.h);
    this.maxw=1.3*this.size;
    this.h=1.3*this.parent.body.h;
  }
  display() {
    ellipseMode(CORNER);
    this.w=this.maxw*abs(this.parent.elytronl.rot);
    push();
    translate(this.location.x, this.location.y);
    rotate(this.side*abs(this.parent.elytronl.rot)*(1+sin(frameCount)));
    ellipse(0, 0, 5, 5);
    noStroke();
    fill(this.parent.wingl.col);
    strokeWeight(this.size*.05/this.size);
    ellipse(-.5*this.w, 0, this.w, this.h);
    pop();
    ellipseMode(CENTER);
  }
}

// === Tab: scarabs ===
let nscarabs=50;
let scarabs=[];
let minsize=.02;
let maxsize=.05;
let maxspeedfactor=1.5;
let ncolors=32;
let colors=[];
let bghue;
let debug=false;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSL, 360, 255, 255, 255);  
  createPalette();
  createScarabs();
}

function draw() {
  background(bghue, 200, 240);
  for (var i=0; i<scarabs.length; i++) {
    scarabs[i].behave();
  }
  if (random(1)>.99 && scarabs.length<nscarabs)createScarabs();
}
function createPalette() {
  for (var i=0; i<ncolors; i++) {
    colors[i]=color(random(360), random(64+i*196/ncolors,255), random(100+i*128/ncolors,255), random(220, 255));
  }
  bghue=random(360);
}
function createScarabs() {
  var scarab=new Scarab();
  scarabs.push(scarab);
  scarab.createParts();
}
function mousePressed() {
  let fs = fullscreen();
  fullscreen(!fs);
  for (var i=0; i<scarabs.length; i++) {
    scarabs[i].size=min(height, width)*random(minsize, maxsize);
  }
}
function windowResized() {
  resizeCanvas(windowWidth, 1.1*windowHeight);
}
function deviceTurned() {
  if (window.screen.width>window.screen.height)resizeCanvas(window.screen.width, window.screen.height);
  else resizeCanvas(1.1*window.screen.height, window.screen.width);
  for (var i=0; i<scarabs.length; i++) {
    scarabs[i].size=min(height, width)*random(minsize, maxsize);
  }
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

